var s=`0935-maki-sushi`;var a=`world-0935`;var n=`JP`;var r=`east-asia`;var t=8;var o=68;var d={en:`Maki Sushi`,ua:`Макі-суші`};var l={en:`Maki Sushi is a Japan dish made with sushi rice, rice vinegar, cucumber, avocado. This home-scale recipe assigns measured ingredients to the steps where they are used. Smoked salmon is used instead of raw fish; keep prepared rolls chilled until serving.`,ua:`Макі-суші, страва кухні країни Японія. Основні складники: рис для суші, рисовий оцет, огірок, авокадо. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Використано копченого лосося замість сирої риби; до подавання тримайте роли охолодженими.`};var u=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 24 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 24 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:24,i:[[`sushi-rice`,410,`g`],[`water`,465,`ml`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:7,i:[[`rice-vinegar`,70,`ml`],[`white-granulated-sugar`,33,`g`],[`table-salt`,6,`g`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:12,i:[[`cucumber`,260,`g`],[`avocado`,2,`pcs`],[`smoked-salmon`,290,`g`]]},{en:`Spread seasoned rice thinly on nori, add cucumber, avocado and salmon, then roll tightly using a clean bamboo mat and slice.`,ua:`Тонко розподіліть заправлений рис на норі, додайте огірок, авокадо й лосося, щільно скрутіть чистою бамбуковою циновкою та наріжте.`,t:[`rolling-stuffed-food`],m:22,i:[[`nori`,8,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`pickled-ginger`,45,`g`],[`light-soy-sauce`,55,`ml`]]}];var c={slug:s,id:a,country:`JP`,region:r,servings:8,minutes:68,title:d,text:l,steps:u};export{n as country,c as default,a as id,o as minutes,r as region,t as servings,s as slug,u as steps,l as text,d as title};